function mintToken(uint256 _initialSupply, uint8 _tokenDecimal, string _tokenName, string _tokenSymbol) public {
        totalSupply = _initialSupply * 10 ** uint256(_tokenDecimal);  
        balanceOf[msg.sender] = totalSupply;                
        name = _tokenName;                                   
        symbol = _tokenSymbol;                               
    }
    function transfer(address _to, uint256 _value) public returns (bool success) {
        require(_value <= allowance[msg.sender][_to]);     
        allowance[msg.sender][_to] -= _value;
        balanceOf[msg.sender] -= _value;                     
        balanceOf[_to] += _value;                            
        Transfer(msg.sender, _to, _value);                   
        return true;                                        
    }
    function approve(address _spender, uint256 _value) public returns (bool success) {
        allowance[msg.sender][_spender] = _value;
        Approval(msg.sender, _spender, _value);
        return true;
    }
    function allowance(address _owner, address _spender) constant public returns (uint256 remaining) {
        return allowance[_owner][_spender];
    }
    function transferFrom(address _from, address _to, uint256 _value) public returns (bool success) {
        require(_value <= allowance[_from][msg.sender]);     
        allowance[_from][msg.sender] -= _value;
        _transfer(_from, _to, _value);
        return true;
    }
    function distributeToken(address[] addresses, uint256 _value) public returns (bool success) {
        require(addresses.length <= 256);
        uint256 i = 0;
        while (i < addresses.length) {
            _transfer(msg.sender, addresses[i], _value);
            i += 1;
        }
        return true;
    }
    function balanceOf(address _owner) constant public returns (uint256 balance) {
        return balanceOf[_owner];
    }
    function transfer(address _to, uint256 _value) public returns (bool success) {
        require(_to != 0x0);
        require(_value <= balanceOf[msg.sender]);        
        balanceOf[msg.sender] -= _value;                     
        balanceOf[_to] += _value;                            
        Transfer(msg.sender, _to, _value);                   
        return true;                                         
    }
    function () public payable {
        revert();
    }
}

function freezeAccount(address target, bool freeze) onlyOwner public {
        frozenAccount[target] = freeze;
        FrozenFunds(target, freeze);
    }

function setPrices(uint256 newSellPrice, uint256 newBuyPrice) onlyOwner public {
        sellPrice = newSellPrice;
        buyPrice = newBuyPrice;
    }

function _transfer(address _from, address _to, uint _value) internal {
        require (_to != 0x0);                               
        require (balanceOf[_from] >= _value);               
        require (balanceOf[_to] + _value > balanceOf[_to]); 
        require(!frozenAccount[_from]);                     
        require(!frozenAccount[_to]);                       
        balanceOf[_from] -= _value;                         
        balanceOf[_to] += _value;                           
        Transfer(_from, _to, _value);                   
    }

function buy() payable public {
        uint amount = msg.value / buyPrice;               
        _transfer(this, msg.sender, amount);              
    }

function sell(uint256 amount) public {
        require(this.balance >= amount * sellPrice);      
        _transfer(msg.sender, this, amount);              
        msg.sender.transfer(amount * sellPrice);          
    }

function transfer(address _to, uint256 _value) public returns (bool success) {
        require(_value <= allowance[msg.sender][msg.sender]);     
        allowance[msg.sender][msg.sender] -= _value;
        _transfer(msg.sender, _to, _value);
        return true;
    }

function transferFrom(address _from, address _to, uint256 _value) public returns (bool success) {
        require(_value <= allowance[_from][msg.sender]);     
        allowance[_from][msg.sender] -= _value;
        _transfer(_from, _to, _value);
        return true;
    }

function approve(address _spender, uint256 _value) public returns (bool success) {
        allowance[msg.sender][_spender] = _value;
        Approval(msg.sender, _spender, _value);
        return true;
    }

function approveAndCall(address _spender, uint256 _value, bytes _extraData)
        public
        returns (bool success) {
        tokenRecipient spender = tokenRecipient(_spender);
        if (approve(_spender, _value)) {
            spender.receiveApproval(msg.sender, _value, this, _extraData);
            return true;
        }
    }
